import axios from 'axios';
import React, { useState, useEffect, useRef } from 'react';
import { useParams, useSearchParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';
import api, { PEXELS_KEY } from '../api';

const SUGGESTIONS = ['Nature','Technology','Travel','Architecture','People','Food','Space','Art','Business','Fashion'];

function handleDownload(url, e) {
  e.stopPropagation();
  e.preventDefault();
  fetch(url)
    .then(function(res) { return res.blob(); })
    .then(function(blob) {
      var blobUrl = window.URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = blobUrl;
      a.download = 'inkwell-image.jpg';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(blobUrl);
    })
    .catch(function() { window.open(url, '_blank'); });
}

function PinCard(props) {
  var img = props.img;
  var onSelect = props.onSelect;
  var imgRef = useRef(null);
  var ratio = img.height / img.width;
  var pt = (ratio * 100).toFixed(2) + '%';

  useEffect(function() {
    if (imgRef.current && imgRef.current.complete) {
      imgRef.current.style.opacity = '1';
      imgRef.current.style.transform = 'translateY(0)';
    }
  }, []);

  return React.createElement(
    'div',
    {
      style: {
        position: 'relative',
        borderRadius: 16,
        overflow: 'hidden',
        cursor: 'pointer',
        background: '#f0f0f0',
        breakInside: 'avoid',
        marginBottom: 12,
        display: 'block',
        width: '100%',
        boxSizing: 'border-box',
      },
      className: 'pin-card',
      onClick: function() { onSelect(img); },
    },
    React.createElement(
      'div',
      { style: { position: 'relative', width: '100%', paddingTop: pt } },
      React.createElement('img', {
        ref: imgRef,
        src: img.src.medium,
        alt: img.alt,
        className: 'pin-img',
        style: {
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          display: 'block',
          borderRadius: 16,
          opacity: 0,
          transform: 'translateY(12px)',
          transition: 'opacity 0.5s ease, transform 0.5s ease',
        },
        onLoad: function() {
          if (imgRef.current) {
            imgRef.current.style.opacity = '1';
            imgRef.current.style.transform = 'translateY(0)';
          }
        },
      }),
      React.createElement(
        'div',
        {
          className: 'pin-overlay',
          style: {
            position: 'absolute',
            inset: 0,
            background: 'linear-gradient(to top, rgba(0,0,0,0.72) 0%, rgba(0,0,0,0.18) 55%, transparent 100%)',
            opacity: 0,
            transition: 'opacity 0.25s ease',
            display: 'flex',
            alignItems: 'flex-end',
            padding: '14px 12px',
            borderRadius: 16,
            pointerEvents: 'none',
          },
        },
        React.createElement(
          'span',
          {
            style: {
              fontSize: 12,
              color: '#fff',
              fontWeight: 600,
              letterSpacing: '0.01em',
              textShadow: '0 1px 4px rgba(0,0,0,0.6)',
            },
          },
          '\uD83D\uDCF7 ' + img.photographer
        )
      ),
      React.createElement(
        'button',
        {
          className: 'pin-dlbtn',
          style: {
            position: 'absolute',
            top: 10,
            right: 10,
            width: 40,
            height: 40,
            borderRadius: '50%',
            background: '#e30d10',
            color: '#fff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            border: 'none',
            cursor: 'pointer',
            zIndex: 10,
            boxShadow: '0 2px 12px rgba(0,0,0,0.35)',
            fontSize: 18,
            fontWeight: 700,
            lineHeight: 1,
            transition: 'opacity 0.2s ease, transform 0.15s ease',
          },
          title: 'Download',
          onClick: function(e) { handleDownload(img.src.original, e); },
        },
        '\u2193'
      )
    )
  );
}

export function ImageSearch() {
  var queryState = useState('');
  var query = queryState[0];
  var setQuery = queryState[1];

  var imagesState = useState([]);
  var images = imagesState[0];
  var setImages = imagesState[1];

  var loadingState = useState(false);
  var loading = loadingState[0];
  var setLoading = loadingState[1];

  var pageState = useState(1);
  var page = pageState[0];
  var setPage = pageState[1];

  var totalState = useState(0);
  var total = totalState[0];
  var setTotal = totalState[1];

  var selectedState = useState(null);
  var selected = selectedState[0];
  var setSelected = selectedState[1];

  var errorState = useState('');
  var error = errorState[0];
  var setError = errorState[1];

  var loadingRef = useRef(false);
  var sentinelRef = useRef(null);
  var currentQueryRef = useRef('');
  var currentPageRef = useRef(1);
  var totalRef = useRef(0);
  var imagesLenRef = useRef(0);
  var searchFnRef = useRef(null);

  var search = function(q, pg) {
    var qq = q !== undefined ? q : query;
    var p = pg !== undefined ? pg : 1;
    if (!qq.trim()) return;
    if (loadingRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    setError('');
    axios.get('https://api.pexels.com/v1/search', {
      headers: { Authorization: PEXELS_KEY },
      params: { query: qq, per_page: 80, page: p },
    }).then(function(res) {
      var data = res.data;
      var photos = data.photos || [];
      if (p === 1) {
        setImages(photos);
        imagesLenRef.current = photos.length;
      } else {
        setImages(function(prev) {
          var next = prev.concat(photos);
          imagesLenRef.current = next.length;
          return next;
        });
      }
      setTotal(data.total_results);
      totalRef.current = data.total_results;
      setPage(p);
      currentPageRef.current = p;
    }).catch(function() {
      setError('Failed to load images. Try again.');
    }).finally(function() {
      setLoading(false);
      loadingRef.current = false;
      setTimeout(function() {
        if (
          sentinelRef.current &&
          !loadingRef.current &&
          imagesLenRef.current > 0 &&
          imagesLenRef.current < totalRef.current
        ) {
          var rect = sentinelRef.current.getBoundingClientRect();
          if (rect.top < window.innerHeight + 800) {
            searchFnRef.current(currentQueryRef.current, currentPageRef.current + 1);
          }
        }
      }, 300);
    });
  };

  searchFnRef.current = search;

  var handleNewSearch = function(q) {
    currentQueryRef.current = q;
    currentPageRef.current = 1;
    imagesLenRef.current = 0;
    totalRef.current = 0;
    setImages([]);
    setPage(1);
    setTotal(0);
    search(q, 1);
  };

  useEffect(function() {
    var observer = new IntersectionObserver(function(entries) {
      var entry = entries[0];
      if (
        entry.isIntersecting &&
        !loadingRef.current &&
        imagesLenRef.current > 0 &&
        imagesLenRef.current < totalRef.current
      ) {
        searchFnRef.current(currentQueryRef.current, currentPageRef.current + 1);
      }
    }, { rootMargin: '800px' });

    var interval = setInterval(function() {
      if (sentinelRef.current) {
        observer.observe(sentinelRef.current);
        clearInterval(interval);
      }
    }, 100);

    return function() {
      observer.disconnect();
      clearInterval(interval);
    };
  }, []);

  return React.createElement(
    'div',
    { style: { background: '#fff', minHeight: '100vh' } },
    React.createElement('style', null, imageSearchCSS),

    React.createElement(
      'div',
      { style: is.header },
      React.createElement(
        'div',
        { className: 'container' },

        React.createElement(
          'div',
          { style: is.searchBar },
          React.createElement(
            'svg',
            { width: 20, height: 20, viewBox: '0 0 24 24', fill: 'none', stroke: '#9b9b9b', strokeWidth: 2 },
            React.createElement('circle', { cx: 11, cy: 11, r: 8 }),
            React.createElement('path', { d: 'm21 21-4.35-4.35' })
          ),
          React.createElement('input', {
            style: is.searchInput,
            placeholder: 'Search for photos...',
            value: query,
            onChange: function(e) { setQuery(e.target.value); },
            onKeyDown: function(e) { if (e.key === 'Enter') handleNewSearch(query); },
          }),
          React.createElement(
            'button',
            { style: is.searchBtn, onClick: function() { handleNewSearch(query); } },
            'Search'
          )
        ),
        React.createElement(
          'div',
          { style: is.chips },
          SUGGESTIONS.map(function(s) {
            return React.createElement(
              'button',
              {
                key: s,
                style: is.chip,
                onClick: function() {
                  setQuery(s);
                  setTimeout(function() { handleNewSearch(s); }, 50);
                },
              },
              s
            );
          })
        )
      )
    ),

    React.createElement(
      'div',
      { className: 'container', style: { paddingBottom: 60 } },

      error ? React.createElement('div', { style: is.error }, error) : null,

      !loading && images.length === 0
        ? React.createElement(
            'div',
            { style: is.empty },
            React.createElement('div', { style: { fontSize: 64, marginBottom: 16 } }, '\uD83D\uDD0D'),
            React.createElement('h3', { style: { fontFamily: 'Lora, serif', fontSize: 22, marginBottom: 8 } }, 'Explore beautiful photos'),
            React.createElement('p', { style: { color: '#9b9b9b', fontSize: 15 } }, 'Search for any topic above to get started.')
          )
        : null,

      images.length > 0
        ? React.createElement(
            'div',
            null,
            React.createElement(
              'div',
              { style: { fontSize: 13, color: '#9b9b9b', margin: '24px 0 16px' } },
              total.toLocaleString() + ' results for "' + currentQueryRef.current + '"'
            ),
            React.createElement(
              'div',
              { style: is.masonryGrid, className: 'masonry-grid' },
              images.map(function(img, idx) {
                return React.createElement(PinCard, { key: img.id + '-' + idx, img: img, onSelect: setSelected });
              }),
              loading
                ? Array.from({ length: 8 }).map(function(_, i) {
                    return React.createElement('div', { key: 'sk' + i, className: 'pin-skeleton' });
                  })
                : null
            ),

            React.createElement('div', { ref: sentinelRef, style: { height: 1 } }),

            loading && images.length > 0
              ? React.createElement(
                  'div',
                  { style: { textAlign: 'center', padding: '24px 0' } },
                  React.createElement('div', { className: 'pin-spinner' })
                )
              : null,

            !loading && images.length >= total && total > 0
              ? React.createElement(
                  'div',
                  { style: { textAlign: 'center', padding: '32px 0', fontSize: 13, color: '#9b9b9b' } },
                  'All ' + total.toLocaleString() + ' images loaded'
                )
              : null
          )
        : null
    ),

    selected
      ? React.createElement(
          'div',
          { style: is.lightbox, onClick: function() { setSelected(null); } },
          React.createElement(
            'div',
            { style: is.lightboxBox, onClick: function(e) { e.stopPropagation(); } },
            React.createElement('button', { style: is.closeBtn, onClick: function() { setSelected(null); } }, '\u2715'),
            React.createElement('img', { src: selected.src.large, alt: selected.alt, style: is.lightboxImg }),
            React.createElement(
              'div',
              { style: is.lightboxFooter },
              React.createElement(
                'div',
                null,
                React.createElement('div', { style: { fontWeight: 600, fontSize: 15, marginBottom: 4 } }, selected.alt || 'Photo'),
                React.createElement(
                  'div',
                  { style: { fontSize: 13, color: '#9b9b9b' } },
                  'by ',
                  React.createElement('strong', null, selected.photographer),
                  ' on Pexels'
                )
              ),
              React.createElement(
                'div',
                { style: { display: 'flex', gap: 10 } },
                React.createElement('a', { href: selected.url, target: '_blank', rel: 'noreferrer', style: is.viewBtn }, 'View on Pexels'),
                React.createElement(
                  'button',
                  { style: is.dlBtn2, onClick: function(e) { handleDownload(selected.src.original, e); } },
                  '\u2193 Original'
                )
              )
            )
          )
        )
      : null
  );
}

const imageSearchCSS = `
  .masonry-grid {
    columns: 4;
    column-gap: 12px;
    margin-top: 8px;
    width: 100%;
    box-sizing: border-box;
    overflow-x: hidden;
  }
  .pin-card {
    break-inside: avoid;
    margin-bottom: 12px;
    display: block;
    width: 100%;
    box-sizing: border-box;
    border-radius: 16px;
    overflow: hidden;
    cursor: pointer;
    background: #f0f0f0;
    position: relative;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    will-change: transform;
  }
  .pin-card:hover {
    transform: translateY(-4px) scale(1.01);
    box-shadow: 0 12px 32px rgba(0,0,0,0.18);
  }
  .pin-card:hover .pin-img {
    transform: translateY(0) scale(1.07) !important;
    filter: brightness(1.06) !important;
  }
  .pin-card:hover .pin-overlay {
    opacity: 1 !important;
  }
  .pin-dlbtn {
    opacity: 0;
    transition: opacity 0.2s ease, transform 0.15s ease !important;
  }
  .pin-card:hover .pin-dlbtn {
    opacity: 1;
  }
  .pin-dlbtn:hover {
    transform: scale(1.12) !important;
    background: #c00a0d !important;
  }
  .pin-dlbtn:active {
    transform: scale(0.92) !important;
  }
  .pin-skeleton {
    break-inside: avoid;
    margin-bottom: 12px;
    display: block;
    width: 100%;
    height: 240px;
    border-radius: 16px;
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: pinShimmer 1.4s infinite;
    box-sizing: border-box;
  }
  @keyframes pinShimmer {
    0%   { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }
  .pin-spinner {
    width: 32px;
    height: 32px;
    border: 3px solid #f0f0f0;
    border-top-color: #e30d10;
    border-radius: 50%;
    animation: pinSpin 0.7s linear infinite;
    margin: 0 auto;
  }
  @keyframes pinSpin {
    to { transform: rotate(360deg); }
  }
  .pin-card:active { opacity: 0.94; }

  @media (max-width: 1200px) {
    .masonry-grid { columns: 3 !important; }
  }
  @media (max-width: 768px) {
    .masonry-grid { columns: 2 !important; column-gap: 10px !important; }
    .pin-card { margin-bottom: 10px !important; }
    .pin-card:hover { transform: none !important; box-shadow: 0 2px 8px rgba(0,0,0,0.08) !important; }
    .pin-card:hover .pin-img { transform: translateY(0) scale(1) !important; filter: brightness(1) !important; }
    .pin-dlbtn { opacity: 1 !important; width: 34px !important; height: 34px !important; top: 8px !important; right: 8px !important; font-size: 15px !important; }
    .pin-overlay { opacity: 1 !important; }
  }
  @media (max-width: 480px) {
    .masonry-grid { columns: 2 !important; column-gap: 8px !important; }
    .pin-card { margin-bottom: 8px !important; border-radius: 10px !important; }
    .pin-skeleton { height: 160px !important; border-radius: 10px !important; }
  }
`;

const is = {
  header:         { background: '#fafafa', borderBottom: '1px solid #e6e6e6', padding: '56px 0 32px' },
  title:          { fontFamily: '"Lora", Georgia, serif', fontSize: 52, fontWeight: 800, background: 'linear-gradient(135deg, #e30d10 0%, #ff6b6b 50%, #242424 100%)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text', marginBottom: 8, letterSpacing: '-0.04em', lineHeight: 1.05 },
  sub:            { fontSize: 17, color: '#6b6b6b', marginBottom: 28, fontStyle: 'italic', letterSpacing: '0.01em' },
  searchBar:      { display: 'flex', alignItems: 'center', gap: 12, maxWidth: 580, background: '#fff', border: '1px solid #e6e6e6', borderRadius: 999, padding: '8px 8px 8px 20px' },
